/* 학습 해설
 * TC Flower·Masked Flow Key와 Hash Lookup
 * Protocol field·tunnel metadata·conntrack 상태 등 구조화된 key로 packet을 분류하려면 mask별 lookup을 관리해야 합니다.
 * Flower는 mask 목록을 순회하며 해당 dissector가 요구하는 key 범위를 초기화하고 metadata·protocol·tunnel·CT·hash·packet header를 추출합니다. Masked key로 filter를 찾고 software 처리 가능한 match면 result와 action을 실행합니다. Post-CT와 zone 정보도 분류 context에 사용합니다.
 * 격리된 namespace에서 tc flower key/mask·ct_state/zone·tunnel field와 skip_sw/skip_hw를 확인합니다. Header field와 skb metadata·hardware parsing capability를 구분하고 offload 요청·성공 상태를 통계로 대조합니다.
 */
TC_INDIRECT_SCOPE int fl_classify(struct sk_buff *skb,
				  const struct tcf_proto *tp,
				  struct tcf_result *res)
{
	struct cls_fl_head *head = rcu_dereference_bh(tp->root);
	bool post_ct = tc_skb_cb(skb)->post_ct;
	u16 zone = tc_skb_cb(skb)->zone;
	struct fl_flow_key skb_key;
	struct fl_flow_mask *mask;
	struct cls_fl_filter *f;

	list_for_each_entry_rcu(mask, &head->masks, list) {
		flow_dissector_init_keys(&skb_key.control, &skb_key.basic);
		fl_clear_masked_range(&skb_key, mask);

		skb_flow_dissect_meta(skb, &mask->dissector, &skb_key);
		/* skb_flow_dissect() does not set n_proto in case an unknown
		 * protocol, so do it rather here.
		 */
		skb_key.basic.n_proto = skb_protocol(skb, false);
		skb_flow_dissect_tunnel_info(skb, &mask->dissector, &skb_key);
		skb_flow_dissect_ct(skb, &mask->dissector, &skb_key,
				    fl_ct_info_to_flower_map,
				    ARRAY_SIZE(fl_ct_info_to_flower_map),
				    post_ct, zone);
		skb_flow_dissect_hash(skb, &mask->dissector, &skb_key);

