/* 학습 해설
 * Shebang·Script Interpreter와 Argv 재구성
 * 텍스트 script를 실행할 때 kernel이 script 문법을 해석하는 것이 아니라 interpreter 실행으로 연결하는 원리를 봅니다.
 * Loader는 #!로 시작하는지 확인하고 고정 buffer 안에서 interpreter 경로와 optional argument를 찾습니다. Buffer가 항상 NUL 종료된다고 가정하지 않으며 경로 잘림은 ENOEXEC입니다. Exec 뒤 접근 불가능한 script는 ENOENT입니다. 기존 argv[0]을 제거하고 script 경로·optional argument·interpreter를 역순으로 copy하여 새 argv를 구성한 뒤 open_exec으로 interpreter file을 연결합니다.
 * 격리된 Linux에서 작은 #!/bin/sh script와 실행 인자를 비교하고 원본의 argc 증가·copy 순서를 적습니다. Shebang optional argument는 shell처럼 임의 개수의 단어로 나누는 parser가 아니며 PATH 검색이 아니라 지정 interpreter 경로를 사용하는 부분을 확인합니다.
 */
static int load_script(struct linux_binprm *bprm)
{
	const char *i_name, *i_sep, *i_arg, *i_end, *buf_end;
	struct file *file;
	int retval;

	/* Not ours to exec if we don't start with "#!". */
	if ((bprm->buf[0] != '#') || (bprm->buf[1] != '!'))
		return -ENOEXEC;

	/*
	 * This section handles parsing the #! line into separate
	 * interpreter path and argument strings. We must be careful
	 * because bprm->buf is not yet guaranteed to be NUL-terminated
	 * (though the buffer will have trailing NUL padding when the
	 * file size was smaller than the buffer size).
	 *
	 * We do not want to exec a truncated interpreter path, so either
	 * we find a newline (which indicates nothing is truncated), or
	 * we find a space/tab/NUL after the interpreter path (which
	 * itself may be preceded by spaces/tabs). Truncating the
	 * arguments is fine: the interpreter can re-read the script to
	 * parse them on its own.
	 */
	buf_end = bprm->buf + sizeof(bprm->buf) - 1;
	i_end = strnchr(bprm->buf, sizeof(bprm->buf), '\n');

/* 학습 해설
 * Binfmt Misc·Format Handler와 Interpreter 수명
 * 외부 format이나 다른 architecture의 실행을 interpreter에 연결하는 kernel 등록 경로와 emulator 자체의 역할을 구분합니다.
 * Loader는 user namespace의 binfmt_misc instance를 찾고 enabled 및 matching handler를 확인해 참조를 얻습니다. Preserve argv0, binary execfd, credential 및 이미 열린 interpreter 옵션에 따라 인자를 구성하고 interpreter file을 연결합니다. 모든 exit에서 handler 참조를 반환하여 동시 unregister와 수명을 맞춥니다. Kernel이 foreign instruction을 직접 emulation하는 함수는 아닙니다.
 * 격리된 namespace에서 이미 등록된 binfmt_misc 상태와 entry의 interpreter·flag를 조회합니다. Magic/mask 또는 extension의 matching과 emulator 동작을 분리하고, credential flag는 권한 선택에 영향을 주므로 실제 policy를 읽습니다.
 */
static int load_misc_binary(struct linux_binprm *bprm)
{
	Node *fmt;
	struct file *interp_file = NULL;
	int retval = -ENOEXEC;
	struct binfmt_misc *misc;

	misc = load_binfmt_misc();
	if (!misc->enabled)
		return retval;

	fmt = get_binfmt_handler(misc, bprm);
	if (!fmt)
		return retval;

	/* Need to be able to load the file after exec */
	retval = -ENOENT;
	if (bprm->interp_flags & BINPRM_FLAGS_PATH_INACCESSIBLE)
		goto ret;

	if (fmt->flags & MISC_FMT_PRESERVE_ARGV0) {
		bprm->interp_flags |= BINPRM_FLAGS_PRESERVE_ARGV0;
	} else {
		retval = remove_arg_zero(bprm);
		if (retval)
			goto ret;

/* 학습 해설
 * BFLT·Flat Executable의 Stack과 NOMMU
 * 가상 메모리 page table을 쓰지 않는 구성에서도 executable data·인자·stack 배치를 준비하는 loader가 필요합니다.
 * Flat loader는 library info를 초기화하고 argc/envc pointer 배열과 NOMMU argument 문자열 공간을 stack 길이에 포함한 뒤 alignment를 맞춥니다. load_flat_file 이후 library data pointer를 사용자 공간에 기록하고 MMU/NOMMU별 인자 stack을 준비합니다. Tables 생성과 platform register 초기화 후 finalize_exec 및 start_thread로 entry와 stack을 설정합니다.
 * 고정 v6.12의 CONFIG_MMU 분기를 비교하고 지원 architecture의 BFLT header·relocation 및 load_flat_file을 연결해 읽습니다. 일반 desktop에서 모든 flat file을 바로 실행할 수 있다고 가정하지 않고 kernel config와 executable ABI를 확인합니다.
 */
static int load_flat_binary(struct linux_binprm *bprm)
{
	struct lib_info libinfo;
	struct pt_regs *regs = current_pt_regs();
	unsigned long stack_len = 0;
	unsigned long start_addr;
	int res;
	int i, j;

	memset(&libinfo, 0, sizeof(libinfo));

	/*
	 * We have to add the size of our arguments to our stack size
	 * otherwise it's too easy for users to create stack overflows
	 * by passing in a huge argument list.  And yes,  we have to be
	 * pedantic and include space for the argv/envp array as it may have
	 * a lot of entries.
	 */
#ifndef CONFIG_MMU
	stack_len += PAGE_SIZE * MAX_ARG_PAGES - bprm->p; /* the strings */
#endif
	stack_len += (bprm->argc + 1) * sizeof(char *);   /* the argv array */
	stack_len += (bprm->envc + 1) * sizeof(char *);   /* the envp array */
	stack_len = ALIGN(stack_len, FLAT_STACK_ALIGN);

	res = load_flat_file(bprm, &libinfo, &stack_len);

/* 학습 해설
 * ELF FDPIC·Load Map과 Interpreter Entry
 * FDPIC executable은 segment의 실제 load 위치와 ABI에 필요한 load map을 함께 전달하는 실행 형식입니다.
 * Loader는 ELF 및 FDPIC 조건·program headers·interpreter 경로를 검증합니다. MMU에서는 non-FDPIC을 일반 loader로 넘기고 NOMMU의 non-FDPIC은 ET_DYN 조건을 봅니다. begin_new_exec 뒤 새 이미지·stack·executable/interpreter mapping·load map tables를 준비합니다. 시작 주소는 interpreter entry가 있으면 그것, 아니면 executable entry이며 오류 정리에서 file과 할당한 map/header를 해제합니다.
 * 지원 ABI의 고정 source와 Documentation을 따라 PT_LOAD·PT_INTERP·FDPIC loadmap을 비교합니다. 일반 ELF section 분석과 실행 segment 배치를 구분하고, 이 loader가 모든 architecture에서 사용되는 것이 아니라 config/ABI 조건을 가진다는 점을 확인합니다.
 */
static int load_elf_fdpic_binary(struct linux_binprm *bprm)
{
	struct elf_fdpic_params exec_params, interp_params;
	struct pt_regs *regs = current_pt_regs();
	struct elf_phdr *phdr;
	unsigned long stack_size, entryaddr;
#ifdef ELF_FDPIC_PLAT_INIT
	unsigned long dynaddr;
#endif
#ifndef CONFIG_MMU
	unsigned long stack_prot;
#endif
	struct file *interpreter = NULL; /* to shut gcc up */
	char *interpreter_name = NULL;
	int executable_stack;
	int retval, i;
	loff_t pos;

	kdebug("____ LOAD %d ____", current->pid);

	memset(&exec_params, 0, sizeof(exec_params));
	memset(&interp_params, 0, sizeof(interp_params));

	exec_params.hdr = *(struct elfhdr *) bprm->buf;
	exec_params.flags = ELF_FDPIC_FLAG_PRESENT | ELF_FDPIC_FLAG_EXECUTABLE;

/* 학습 해설
 * Eventfd·64bit Counter와 Wait Queue
 * Event를 file descriptor readiness로 연결하면 epoll 기반 프로그램과 kernel producer가 하나의 알림 인터페이스를 사용할 수 있습니다.
 * Eventfd read는 최소 u64 buffer를 요구합니다. Counter가 0이고 nonblocking/NOWAIT이면 EAGAIN, 아니면 interruptible wait를 합니다. Counter 소비 helper는 semaphore mode면 1을 읽어 1 감소, 일반 mode면 전체 값을 읽어 0으로 만듭니다. Lock 아래 counter 소비와 writer wakeup을 처리한 뒤 userspace에 값을 copy합니다. Copy 실패가 앞선 counter 소비를 자동 복원하지는 않습니다.
 * Linux·WSL에서 eventfd를 만드는 작은 C 예제로 write u64·read u64·poll을 비교합니다. EFD_SEMAPHORE와 NONBLOCK mode, 한 알림이 한 payload message를 보존하는 queue와 다르다는 점을 확인합니다.
 */
static ssize_t eventfd_read(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct eventfd_ctx *ctx = file->private_data;
	__u64 ucnt = 0;

	if (iov_iter_count(to) < sizeof(ucnt))
		return -EINVAL;
	spin_lock_irq(&ctx->wqh.lock);
	if (!ctx->count) {
		if ((file->f_flags & O_NONBLOCK) ||
		    (iocb->ki_flags & IOCB_NOWAIT)) {
			spin_unlock_irq(&ctx->wqh.lock);
			return -EAGAIN;
		}

		if (wait_event_interruptible_locked_irq(ctx->wqh, ctx->count)) {
			spin_unlock_irq(&ctx->wqh.lock);
			return -ERESTARTSYS;
		}
	}
	eventfd_ctx_do_read(ctx, &ucnt);
	current->in_eventfd = 1;
	if (waitqueue_active(&ctx->wqh))
		wake_up_locked_poll(&ctx->wqh, EPOLLOUT);
	current->in_eventfd = 0;

/* 학습 해설
 * Signalfd·Signal을 Record I/O로 소비
 * 비동기 signal 처리를 event loop의 file read와 연결하면 signal 정보와 I/O readiness를 함께 다룰 수 있습니다.
 * Read는 buffer 길이를 128byte signalfd_siginfo record 수로 나누며 최소 하나가 없으면 EINVAL입니다. Mask에 맞는 pending signal을 dequeue하고 layout별 정보를 zero-initialized record에 copy합니다. 처음은 blocking일 수 있지만 하나를 읽은 뒤에는 nonblock으로 전환합니다. 여러 record 뒤 실패하면 읽은 total을 우선 반환합니다.
 * Linux·WSL에서 대상 signal을 해당 thread에서 block한 뒤 signalfd와 poll/epoll을 연결하는 작은 예제를 만듭니다. Signal mask·thread/shared pending·read 소비를 구분하고 SIGKILL/SIGSTOP처럼 차단할 수 없는 signal 조건은 생성 경로에서 확인합니다.
 */
static ssize_t signalfd_read_iter(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct signalfd_ctx *ctx = file->private_data;
	size_t count = iov_iter_count(to);
	ssize_t ret, total = 0;
	kernel_siginfo_t info;
	bool nonblock;

	count /= sizeof(struct signalfd_siginfo);
	if (!count)
		return -EINVAL;

	nonblock = file->f_flags & O_NONBLOCK || iocb->ki_flags & IOCB_NOWAIT;
	do {
		ret = signalfd_dequeue(ctx, &info, nonblock);
		if (unlikely(ret <= 0))
			break;
		ret = signalfd_copyinfo(to, &info);
		if (ret < 0)
			break;
		total += ret;
		nonblock = 1;
	} while (--count);

	return total ? total: ret;

/* 학습 해설
 * Timerfd·만료 횟수와 주기 재설정
 * Timer 알림을 fd에 연결해도 만료 횟수·clock 종류·시간 변경 취소를 따로 이해해야 합니다.
 * Read는 최소 u64 buffer를 요구하고 ticks가 준비될 때까지 기다리거나 nonblocking EAGAIN 경로를 사용합니다. 취소된 clock 상태면 ticks/expired를 지우고 ECANCELED입니다. 만료된 periodic timer는 read에서 forward_now로 지나간 횟수를 반영하고 재시작하며 누적 ticks를 소비합니다. 매우 짧은 주기의 callback 폭주를 피하려고 재설정을 read 경로에서 처리한다는 주석이 있습니다.
 * Linux·WSL에서 timerfd_create/settime 후 epoll과 u64 read를 연결해 지연 read의 누적 만료를 비교합니다. CLOCK_MONOTONIC/REALTIME·absolute time·cancel-on-set 조건을 확인하고 반환값을 경과 초가 아니라 만료 횟수로 해석합니다.
 */
static ssize_t timerfd_read_iter(struct kiocb *iocb, struct iov_iter *to)
{
	struct file *file = iocb->ki_filp;
	struct timerfd_ctx *ctx = file->private_data;
	ssize_t res;
	u64 ticks = 0;

	if (iov_iter_count(to) < sizeof(ticks))
		return -EINVAL;

	spin_lock_irq(&ctx->wqh.lock);
	if (file->f_flags & O_NONBLOCK || iocb->ki_flags & IOCB_NOWAIT)
		res = -EAGAIN;
	else
		res = wait_event_interruptible_locked_irq(ctx->wqh, ctx->ticks);

	/*
	 * If clock has changed, we do not care about the
	 * ticks and we do not rearm the timer. Userspace must
	 * reevaluate anyway.
	 */
	if (timerfd_canceled(ctx)) {
		ctx->ticks = 0;
		ctx->expired = 0;
		res = -ECANCELED;
	}

/* 학습 해설
 * PIDFS·PID 객체를 File 참조로 연결
 * 프로세스 숫자만 보관하면 종료 뒤 재사용된 PID와 혼동할 수 있어 객체 참조를 가진 fd 인터페이스가 필요합니다.
 * PIDFS alloc은 get_pid로 PID 객체 참조를 얻어 stashed path 생성에 전달합니다. 실패는 ERR_PTR이고 성공 path는 dentry_open으로 file에 연결한 뒤 path_put합니다. PID 객체의 수명과 열린 file의 참조를 통해 숫자 재사용과 객체 identity를 구분하는 경로입니다. PID 참조를 가진다고 해당 프로세스가 계속 실행 중이라는 보장은 아닙니다.
 * Linux·WSL의 지원 kernel에서 pidfd_open·poll과 PID 종료를 작은 예제로 관찰하고 고정 source의 pidfd file operations 및 pidfs path helper를 연결합니다. PID number·struct pid·task_struct·살아 있는 process 상태를 구분합니다.
 */
struct file *pidfs_alloc_file(struct pid *pid, unsigned int flags)
{

	struct file *pidfd_file;
	struct path path;
	int ret;

	ret = path_from_stashed(&pid->stashed, pidfs_mnt, get_pid(pid), &path);
	if (ret < 0)
		return ERR_PTR(ret);

	pidfd_file = dentry_open(&path, flags, current_cred());
	path_put(&path);
	return pidfd_file;
}

void __init pidfs_init(void)
{
	pidfs_mnt = kern_mount(&pidfs_type);
	if (IS_ERR(pidfs_mnt))
		panic("Failed to mount pidfs pseudo filesystem");
}

